       "day": {
        "weekday": "FRI",
        "nth": 2
       }
      },
      {
       "month_of": 11,
       "day": {
        "weekday": "FRI",
        "nth": 2
       }
      }
     ]
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "INTEREST_CALCULATED"
   }
  },
  {
   "rule_id": "R-KBGL-S2-R07-02",
   "status": "OK",
   "label": "이자 계산 시점 변경",
   "source": {
